{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "དུས་འཁོར་རྩ་རྒྱུད་ལས།",
      "head": "དབྱུང་བ་ཡིས་ནི་མཁྲིས་པའི་",
      "tail": "པ་བསྡམས་པ་ཡིས་ནི་སེལ་བར་འགྱུར། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཤོང་འགྱུར་ལས།",
      "head": "ཐུར་སེལ་བསྐུམ་ན་འདོད་པར་",
      "tail": "ལྟེ་བའི་རྩ་བར་གཞན་པ་དག་ཀྱང་ངོ་། །"
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟར་རྫས་སྔགས་རླུང་གསུམ་གྱི། ། ཐིག་ལེ་མ་རིག་དང་འབྲེལ་བས། ། འཁོར་བ་བསྐྱེད་པར་གསུངས་པ་སྟེ། ། ཐབས་ཀྱིས་ཟིན་པས་གཉེན་པོར་བཤད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བརྟག་གཉིས་ལས།",
      "head": "སྐྱེ་བོ་མི་ཟད་པ་ཡི་ལས། ། གང་དང་གང་གིས་འཆིང་འགྱུར་བ། ། ཐབས་དང་བཅས་ན་དེ་ཉིད་ཀྱིས། ། སྲིད་པའི་འཆིང་བ་ལས་གྲོལ་འགྱུར། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སྒོམ་པར་བྱེད་པའི་རྒྱུ་མཚན་ཡང་། ། བཅོམ་ལྡན་རྡོ་རྗེ་སེམས་དཔའ་ཡིས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཡུན་རིང་ཆགས་ཆེན་དབང་སོང་བས། ། སྲིད་པ་གསུམ་དུ་སྐྱེས་པ་རྣམས། ། དེ་དག་གྲོལ་བའི་དོན་དུ་ནི། ། རྫས་ཀྱི་ཐིག་ལེ་གསུངས་པ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཞེ་སྡང་ཆེན་པོའི་དབང་སོང་བས། ། མི་གང་མི་སྲུན་པ་ཡི་ལུས། ། དེ་རྣམས་མྱུར་དུ་གྲོལ་དོན་དུ། ། སྔགས་ཀྱི་ཐིག་ལེ་གསུངས་པ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "གཏི་མུག་ཆེན་པོས་ཀུན་ནས་འཁྲུལ། ། སྲིད་སྐྱོབ་དངོས་གྲུབ་འབྲས་བུ་བརྒྱད། ། ཐོབ་ཕྱིར་ཡེ་ཤེས་འབྲས་བུ་ནི། ། རླུང་གི་ཐིག་ལེ་གསུངས་པ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟར་རྩ་རླུང་ཐིག་ལེ་གསུམ། ། རྟེན་ཅིང་འབྲེལ་བར་སྣང་བ་ནི། ། རྟེན་གྱུར་རྡོ་རྗེའི་ལུས་ཞེས་གསུངས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "བཙུན་མོའི་བྷ་ག་བདེ་ཆེན་དུ། ། སོན་པ་སུམ་ཅུ་སོ་གཉིས་མཚན། ། གཙོ་བོ་དཔེ་བྱད་བརྒྱད་ཅུར་ལྡན། ། ཁུ་བ་ཞེས་བྱའི་རྣམ་པར་གནས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་མེད་ན་ནི་བདེ་མེད་འགྱུར། ། བདེ་བ་མེད་ན་དེ་མེད་འགྱུར། ། ནུས་པ་མེད་ཕྱིར་བལྟོས་དང་བཅས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ལྷ་ཡི་རྣལ་འབྱོར་ལས་བདེ་བ། ། དེ་ཉིད་སངས་རྒྱས་དངོས་པོ་མིན། ། དེ་ཉིད་དངོས་མེད་ཚུལ་ཡང་མིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱུད་བླ་ལས།",
      "head": "སྦྱིན་དང་ཚུལ་ཁྲིམས་བཟོད་ལ་",
      "tail": "ཞེས་སོགས་ཀྱིས་བསྟན་པའི་རྣམ་"
    },
    {
      "label": "QUOTE",
      "head": "དེ་ནས་རྣམ་ཤེས་སོགས་འབྲེལ་བ། ། མདོར་བསྡུས་རགས་པ་བཤད་པར་བྱ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཐོག་མར་བསྐྱེད་ཚུལ་གོང་དུ་བཤད། ། གནས་དུས་གནས་སྐབས་བཞི་ཡིན་ཏེ། ། གཉིད་དང་རྨི་ལམ་སྙོམས་འཇུག་དང་། ། ཐ་མལ་དུས་དང་རྣམ་པ་བཞི། ། མ་དག་སྐུ་བཞིའི་གནས་སྐབས་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དབྱེ་བ་རྣམ་པ་མང་བཤད་ཀྱང་། ། གཉིད་དུས་ཀུན་གཞི་གཙོ་བོ་སྟེ། ། སྙིང་ག་ཆོས་ཀྱི་འཁོར་ལོར་གནས། ། ཚོགས་དྲུག་མི་གསལ་གཅིག་ཏུ་བསྡུས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དུས་འཁོར་རྩ་རྒྱུད་ལས།",
      "head": "སད་དང་རྨི་ལམ་གཉིད་མཐུག་",
      "tail": "བཞི་པ་དབང་པོ་གཉིས་སྐྱེ་བདེ། །"
    },
    {
      "label": "QUOTE",
      "head": "དག་ན་འོད་གསལ་འབྲས་བུ་ནི། ། མེ་ལོང་ལྟ་བུ་ཞེས་ཀྱང་བྱ། ། ཆོས་སྐུ་སྤྲོས་བྲལ་ངོ་བོ་ཉིད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "བག་ཆགས་བརྟེན་ཀྱང་མི་གསལ་ཞིང་། ། འདུ་བྱེད་གཡོ་བའི་རྐྱེན་ཡོད་ཕྱིར། ། མ་རིག་དྲི་མ་ཅན་ཞེས་བྱ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "གང་ཟག་ཆོས་ལ་བདག་མེད་པ། ། གཅིག་དང་ཕྱེད་དང་གཉིས་དང་གཉིས། ། རིམ་པར་གཉེན་པོའི་ཤེས་པ་སྟེ། ། དེས་སྦྱངས་ཐེག་གསུམ་སོ་སོ་ཡི། ། རྒྱུན་མཐའ་རྡོ་རྗེ་ལྟ་བུ་ཡིས། ། དྲི་བཅོམ་དག་པ་གསུམ་ཐོབ་གསུངས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ཕྱིར་གསལ་ལ་མི་རྟོག་པའི། ། ཉིན་མཚན་གཉིས་ཀྱི་འོད་གསལ་བསྒོམ། ། རྣམ་ཀུན་མཆོག་ལྡན་སྟོང་པ་ཉིད་། ། ཕྱག་རྒྱ་ཆེ་ལ་རོལ་པར་བྱ། །",
      "tail": ""
    }
  ]
}
